from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from typing import List, Optional
from datetime import datetime
import httpx

app = FastAPI(title="Orders Service", version="1.0.0")

# CORS middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Data models
class OrderItem(BaseModel):
    product_id: int
    quantity: int
    price: float

class Order(BaseModel):
    id: int
    user_id: int
    items: List[OrderItem]
    total: float
    status: str
    created_at: str

class CreateOrder(BaseModel):
    user_id: int
    items: List[OrderItem]

# In-memory database
orders_db = [
    {
        "id": 1,
        "user_id": 1,
        "items": [
            {"product_id": 1, "quantity": 2, "price": 999.99},
            {"product_id": 2, "quantity": 1, "price": 799.99}
        ],
        "total": 2799.97,
        "status": "completed",
        "created_at": "2024-01-15T10:30:00"
    },
    {
        "id": 2,
        "user_id": 2,
        "items": [
            {"product_id": 3, "quantity": 1, "price": 29.99}
        ],
        "total": 29.99,
        "status": "pending",
        "created_at": "2024-01-16T14:20:00"
    }
]

@app.get("/")
def read_root():
    return {
        "service": "Orders Service",
        "version": "1.0.0",
        "status": "running",
        "endpoints": [
            "/orders",
            "/orders/{order_id}",
            "/orders/user/{user_id}",
            "/health"
        ]
    }

@app.get("/health")
def health_check():
    return {"status": "healthy", "service": "orders"}

@app.get("/orders", response_model=List[Order])
def get_orders():
    """Get all orders"""
    return orders_db

@app.get("/orders/{order_id}", response_model=Order)
def get_order(order_id: int):
    """Get a specific order by ID"""
    order = next((order for order in orders_db if order["id"] == order_id), None)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@app.get("/orders/user/{user_id}", response_model=List[Order])
def get_user_orders(user_id: int):
    """Get all orders for a specific user"""
    user_orders = [order for order in orders_db if order["user_id"] == user_id]
    return user_orders

@app.post("/orders", response_model=Order, status_code=201)
def create_order(order: CreateOrder):
    """Create a new order"""
    # Calculate total
    total = sum(item.price * item.quantity for item in order.items)

    # Create new order
    new_order = {
        "id": len(orders_db) + 1,
        "user_id": order.user_id,
        "items": [item.dict() for item in order.items],
        "total": total,
        "status": "pending",
        "created_at": datetime.now().isoformat()
    }

    orders_db.append(new_order)
    return new_order

@app.put("/orders/{order_id}/status")
def update_order_status(order_id: int, status: str):
    """Update order status"""
    order = next((order for order in orders_db if order["id"] == order_id), None)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")

    valid_statuses = ["pending", "processing", "shipped", "delivered", "cancelled"]
    if status not in valid_statuses:
        raise HTTPException(status_code=400, detail=f"Invalid status. Must be one of: {valid_statuses}")

    order["status"] = status
    return order

@app.delete("/orders/{order_id}")
def delete_order(order_id: int):
    """Delete an order"""
    global orders_db
    order = next((order for order in orders_db if order["id"] == order_id), None)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")

    orders_db = [o for o in orders_db if o["id"] != order_id]
    return {"message": "Order deleted successfully"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8003)

